# Config lives next to this file if writable, else in the home folder,
# so the lone .py works from anywhere (e.g. ~/Downloads).
def _resolve_config_path():
    here = os.path.dirname(os.path.abspath(__file__))
    candidate = os.path.join(here, 'rops-calculator-config.json')
    try:
        if os.path.exists(candidate):
            return candidate
        # test writability of the folder
        testfile = os.path.join(here, '.rops-write-test')
        with open(testfile, 'w') as _t:
            _t.write('')
        os.remove(testfile)
        return candidate
    except Exception:
        return os.path.join(os.path.expanduser('~'), '.rops-calculator-config.json')
CONFIG_FILE = _resolve_config_path()

